import Button from '@mui/material/Button';
import '../styles/Cart.css';

function Cart() {
    const tshirtPrice = 8, pullPrice = 10, pantalonPrice = 15;
    const totalPrice = tshirtPrice + pullPrice + pantalonPrice;
    return (
        <div className='cart'>
            <h2>Panier</h2>
            <ul>
                <li>t-shirt : {tshirtPrice}€</li>
                <li>pull : {pullPrice}€</li>
                <li>pantalon : {pantalonPrice}€</li>
            </ul>
            <div className="total">
                Total : {tshirtPrice + pullPrice + pantalonPrice}€
            </div>
            <br />
            <Button variant="contained" color="secondary">Vider le panier</Button>
        </div>
    );
}


export default Cart
